        : fbBuilder.writeString(_UNITS!);
    final int? STATISTICSOffset = _STATISTICS == null ? null
        : fbBuilder.writeList(_STATISTICS!.map((b) => b.getOrCreateOffset(fbBuilder)).toList());
    final int? PROVENANCEOffset = _PROVENANCE?.getOrCreateOffset(fbBuilder);
